package com.elkin.reyes.service;
import com.elkin.reyes.api.ApiException; import com.elkin.reyes.model.*; import com.elkin.reyes.repository.*; import com.elkin.reyes.soap.EstrellaAdapter; import java.sql.*; import java.util.*;
public class CaravanaService {
 private final CaravanaRepository cr=new CaravanaRepository(); private final ParadaRepository pr=new ParadaRepository(); private final EstrellaAdapter estrella=new EstrellaAdapter();
 private <T>T sql(Sql<T> f){try{return f.run();}catch(SQLException e){String m=e.getMessage()==null?"":e.getMessage().toLowerCase();if(m.contains("unique")||m.contains("primary key"))throw new ApiException(409,"DUPLICADO","El rey, la ofrenda o el orden de parada ya está registrado");if(m.contains("foreign key"))throw new ApiException(404,"CARAVANA_NO_EXISTE","La caravana indicada no existe");throw new RuntimeException(e);}}
 @FunctionalInterface interface Sql<T>{T run()throws SQLException;}
 private void validateCaravana(String rey,String ofrenda,String origen,int camellos){if(!List.of("MELCHOR","GASPAR","BALTASAR").contains(rey))throw new ApiException(400,"REY_INVALIDO","rey debe ser MELCHOR, GASPAR o BALTASAR");if(!List.of("ORO","INCIENSO","MIRRA").contains(ofrenda))throw new ApiException(400,"OFRENDA_INVALIDA","ofrenda debe ser ORO, INCIENSO o MIRRA");if(origen==null||origen.isBlank())throw new ApiException(400,"ORIGEN_REQUERIDO","origen es obligatorio");if(camellos<1||camellos>12)throw new ApiException(400,"CANTIDAD_CAMELLOS_INVALIDA","camellos debe estar entre 1 y 12");}
 public Caravana create(Map<String,Object>b){String rey=upper(str(b,"rey")),of=upper(str(b,"ofrenda")),ori=str(b,"origen");int cam=num(b,"camellos");validateCaravana(rey,of,ori,cam);return sql(()->cr.create(rey,of,ori,cam));}
 public List<Caravana> all(String estado){if(estado!=null&&!List.of("DETENIDA","EN_CAMINO","EN_BELEN","OFRENDA_ENTREGADA").contains(estado))throw new ApiException(400,"ESTADO_INVALIDO","Filtro estado no válido");return sql(()->cr.all(estado));}
 public Caravana get(long id){Caravana c=sql(()->cr.find(id));if(c==null)throw new ApiException(404,"CARAVANA_NO_ENCONTRADA","No existe la caravana");return c;}
 public Caravana update(long id,Map<String,Object>b){Caravana c=get(id);if(!c.estado().equals("DETENIDA"))throw new ApiException(409,"CARAVANA_NO_EDITABLE","Solo se modifica una caravana DETENIDA");String rey=upper(str(b,"rey")),of=upper(str(b,"ofrenda")),ori=str(b,"origen");int cam=num(b,"camellos");validateCaravana(rey,of,ori,cam);sql(()->{cr.update(id,rey,of,ori,cam);return null;});return get(id);}
 public Caravana changeState(long id,String next){Caravana c=get(id);Set<String> valid=switch(c.estado()){case "DETENIDA"->Set.of("EN_CAMINO");case "EN_CAMINO"->Set.of("DETENIDA","EN_BELEN");case "EN_BELEN"->Set.of("OFRENDA_ENTREGADA");default->Set.of();};if(!valid.contains(next))throw new ApiException(409,"TRANSICION_INVALIDA","No se permite pasar de "+c.estado()+" a "+next);
   if(next.equals("EN_CAMINO")){try{var ruta=estrella.consultar(c.origen());if(ruta.visibilidad().equals("NUBLADA"))throw new ApiException(422,"RUTA_NUBLADA","La estrella indica visibilidad NUBLADA");}catch(ApiException e){throw e;}catch(Exception e){throw new ApiException(503,"SOAP_NO_DISPONIBLE","No se pudo consultar el servicio de la Estrella; la caravana sigue DETENIDA");}}
   if(next.equals("EN_BELEN")){boolean pendientes=sql(()->pr.byCaravana(id).stream().anyMatch(p->p.estado().equals("PLANIFICADA")));if(pendientes)throw new ApiException(422,"PARADAS_PENDIENTES","No puede llegar a Belén mientras existan paradas PLANIFICADAS");}
   sql(()->{cr.state(id,next);return null;});return get(id);
 }
 public List<Parada> stops(long id){get(id);return sql(()->pr.byCaravana(id));}
 public Parada addStop(long id,Map<String,Object>b){Caravana c=get(id);if(Set.of("EN_BELEN","OFRENDA_ENTREGADA").contains(c.estado()))throw new ApiException(409,"ITINERARIO_CERRADO","No se pueden agregar paradas a esta caravana");String ciudad=str(b,"ciudad");int orden=num(b,"orden"),dias=num(b,"diasEstancia");if(ciudad==null||ciudad.isBlank()||orden<1||dias<0||dias>7)throw new ApiException(400,"PARADA_INVALIDA","ciudad es obligatoria, orden debe ser >=1 y diasEstancia entre 0 y 7");return sql(()->pr.create(id,ciudad,orden,dias));}
 public Parada changeStop(long id,String estado){Parada p=sql(()->pr.find(id));if(p==null)throw new ApiException(404,"PARADA_NO_ENCONTRADA","No existe la parada");if(!List.of("PLANIFICADA","CUMPLIDA","CANCELADA").contains(estado))throw new ApiException(400,"ESTADO_PARADA_INVALIDO","Estado de parada no válido");if(!p.estado().equals("PLANIFICADA"))throw new ApiException(409,"PARADA_NO_MODIFICABLE","Solo se actualizan paradas PLANIFICADAS");if(estado.equals("CUMPLIDA")){boolean prev=sql(()->pr.byCaravana(p.caravanaId()).stream().anyMatch(x->x.orden()<p.orden()&&x.estado().equals("PLANIFICADA")));if(prev)throw new ApiException(409,"ORDEN_DE_PARADAS","Primero debes cumplir o cancelar las paradas anteriores");}sql(()->{pr.state(id,estado);return null;});return sql(()->pr.find(id));}
 public void deleteStop(long id){Parada p=sql(()->pr.find(id));if(p==null)throw new ApiException(404,"PARADA_NO_ENCONTRADA","No existe la parada");if(!p.estado().equals("PLANIFICADA"))throw new ApiException(409,"PARADA_NO_ELIMINABLE","Solo se eliminan paradas PLANIFICADAS");sql(()->{pr.delete(id);return null;});}
 public Map<String,Object> itinerary(long id){List<Parada> ps=stops(id);int days=ps.stream().mapToInt(Parada::diasEstancia).sum();long pending=ps.stream().filter(p->p.estado().equals("PLANIFICADA")).count();return Map.of("caravanaId",id,"paradas",ps,"diasTotales",days,"paradasPendientes",pending);}
 private String str(Map<String,Object>b,String k){Object v=b.get(k);return v==null?null:v.toString().trim();}
 private String upper(String s){return s==null?null:s.toUpperCase(Locale.ROOT);}
 private int num(Map<String,Object>b,String k){try{return Integer.parseInt(String.valueOf(b.get(k)));}catch(Exception e){throw new ApiException(400,"CAMPO_INVALIDO","El campo "+k+" es obligatorio y debe ser numérico");}}
}
